function ensureWebTestCharacter(force=false){
 let test=db.chars.find(x=>x.id===WEB_TEST_CHARACTER_ID);let provisioned=false;try{provisioned=localStorage.getItem('codice-web-test-provisioned-v1')==='true';}catch{}
 if(!test&&(force||!provisioned)){test=JSON.parse(JSON.stringify(WEB_TEST_CHARACTER_SEED));db.chars.push(test);if(!db.selected)db.selected=test.id;save();}
 if(test)try{localStorage.setItem('codice-web-test-provisioned-v1','true');}catch{}
 return test;
}
function openWebTestCharacter(){const test=ensureWebTestCharacter(true);if(!test)return;db.selected=test.id;save();document.getElementById('play-dialog')?.close();render();}
async function protectWebStorage(){let protectedStorage=false;try{protectedStorage=await navigator.storage?.persist?.()||false;}catch{}window.codiceWebStorageStatus.persistent=protectedStorage;toast(webEnglish()?(protectedStorage?'Persistent browser storage enabled. Keep an exported backup too.':'Your browser did not grant persistent storage. Export a JSON backup to protect your characters.'):(protectedStorage?'Armazenamento persistente ativado. Mantenha também um backup exportado.':'O navegador não concedeu armazenamento persistente. Exporte um backup JSON para proteger suas fichas.'));}
const webSettings=openSettings48;openSettings48=function(){const out=webSettings();const section=document.createElement('section');section.className='web-settings';section.innerHTML=`<h3>${webEnglish()?"Codex Web":'Códice Web'}</h3><p class="web-version">${CODICE_WEB_VERSION}</p><p>${webEnglish()?'Your characters are saved in this browser. Import a JSON export from the Android app to bring a character here.':'Suas fichas ficam salvas neste navegador. Importe o JSON exportado pelo APK para trazer uma ficha para cá.'}</p><p>${webEnglish()?'Updates keep your characters on this same address and browser. A local recovery copy is saved automatically. Clearing browser data or using another device requires an exported JSON backup.':'Os updates preservam suas fichas neste mesmo endereço e navegador. Uma cópia de recuperação local é salva automaticamente. Limpar os dados do navegador ou usar outro aparelho exige um backup JSON exportado.'}</p><div class="web-actions"><button type="button" onclick="openWebTestCharacter()">${webEnglish()?'Open test character':'Abrir ficha de testes'}</button><button type="button" onclick="protectWebStorage()">${webEnglish()?'Protect browser storage':'Proteger armazenamento'}</button><button type="button" onclick="exportChar()">${webEnglish()?'Export character backup':'Exportar backup da ficha'}</button><button type="button" onclick="importWebCharacter()">${webEnglish()?'Import character':'Importar ficha'}</button><button type="button" onclick="installCodiceWeb()">${webEnglish()?'Add to home screen':'Adicionar à tela inicial'}</button><button type="button" onclick="checkWebUpdate(true)">${webEnglish()?'Check for updates':'Verificar atualizações'}</button></div>`;document.getElementById('play-body').append(section);localize48();return out;};
async function checkWebUpdate(manual=false){if(!manual&&Date.now()-webVersionCheckedAt<30000)return;webVersionCheckedAt=Date.now();try{const response=await fetch('version.json',{cache:'no-store',credentials:'same-origin'});if(!response.ok||!response.headers.get('content-type')?.includes('json'))throw Error();const latest=await response.json();if(latest.version!==CODICE_WEB_VERSION){let notice=document.getElementById('web-update');if(!notice){notice=document.createElement('div');notice.id='web-update';notice.setAttribute('role','status');document.body.append(notice);}notice.innerHTML=`<span>${webEnglish()?'An update is ready. Your saved characters will be kept.':'Uma atualização está pronta. Suas fichas salvas serão mantidas.'}</span><button type="button" onclick="location.reload()">${webEnglish()?'Reload':'Recarregar'}</button>`;}else if(manual)toast(webEnglish()?'You are using the latest version.':'Você está usando a versão mais recente.');}catch{if(manual)toast(webEnglish()?'Could not check right now. Try again when online.':'Não foi possível verificar agora. Tente novamente com conexão.');}}
window.addEventListener('online',()=>checkWebUpdate());window.addEventListener('focus',()=>checkWebUpdate());
if('serviceWorker'in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('sw.js',{updateViaCache:'none'}).then(registration=>registration.update()).catch(()=>{}));
ensureWebTestCharacter();render();document.documentElement.classList.remove('codice-loading');document.getElementById('web-loading')?.remove();checkWebUpdate();
